def footer_links_and_order(apps, schema_editor):
    """Ссылки в подвале раньше брались из настроек (политика и правила) — переносим их на галочку страниц.
    Порядок — прежний, по алфавиту."""
    InfoPage = apps.get_model("core", "InfoPage")
    SiteSettings = apps.get_model("core", "SiteSettings")
    site = SiteSettings.objects.filter(pk=1).first()
    selected = [site.privacy_page_id, site.safety_page_id] if site else []
    InfoPage.objects.filter(models.Q(pk__in=[pk for pk in selected if pk]) | models.Q(slug=PRIVACY_SLUG)).update(
        show_in_footer=True
    )
    for order, pk in enumerate(InfoPage.objects.order_by("title", "id").values_list("pk", flat=True)):
        InfoPage.objects.filter(pk=pk).update(order=order)


